from __future__ import absolute_import
from selenium.webdriver.common.by import By
from .LoginPage import NomLoginPage
from .common_page import CommonPage
import time


class Storage(CommonPage):
    """
    The class corresponding to 'Storage' page on web, all operations under Storage
    page will be implemented or added in its corresponding classes.
    """
    _instance_dict = {}

    def __init__(self, driver):
        if not self._instance_dict:
            self._instance_dict = {
                "Plan View": PlanViewPage(driver)
            }
        super(Storage, self).__init__(driver, self._instance_dict)


class PlanViewPage(NomLoginPage):
    MENU_ROUTE_LIST = ['plan-view']
    _USE_CASE_ELEMENT_ON_STORAGE_PAGE = \
        """//div[@class="flex-select__select"]//div[@class="flex-select-edited-label"]//div[contains(text(), "Plans")
         or contains(text(), "Configuration templates")
         or contains(text(), "Integration plans")
         or contains(text(), "Site configuration files") 
         or contains(text(), "Software packages") 
         or contains(text(), "Save")
         or contains(text(), "Consistency reports")
         ]"""
    _USE_CASE_ON_STORAGE_PAGE = '//div[@class="flex-select-edited-label__left" and text()="{}"]'
    _DROP_DOWN_OPTION_OF_PLANS = '//*[@id="PROVIDED-Plans-0"]'
    _USE_CASE_OPTION_MAP = {
                            "Integration plans": '//*[@id="PROVIDED-Integration_plans-0"]',
                            "Plans": '//*[@id="PROVIDED-Plans-0"]',
                            "SW packages": '//*[@id="PROVIDED-SW_packages-0"]',
                            "Consistency reports": '//*[@id="PROVIDED-Consistency_reports-0"]'
                            }

    _STORAGE_PAGE_LOAD_FINISH_XPATH = '//div[@data-key="plan-view" and contains(@style, "position: fixed")]'

    ALL_FILTER_CONDITIONS = ['plan_name', 'description', 'date', 'Owner',
                             'import_status', 'download_status', 'activation_status', 'report_name', 'condition'
                             ]
    _FILTER_FIRST_FIELD_XPATH = '//input[contains(@id, "first-input-first-field")]'
    _FILTER_CONDITION_INPUT_XPATH = '//input[contains(@id, "first-input-condition")]'
    _FILTER_CONDITION_SELECT_XPATH = '//div[@data-test="ccfk-list-item" and contains(text(), "{}")]//..'
    _FILTER_QUERY_INPUT_XPATH = '//input[contains(@id, "first-input-query")]'
    _FILTER_QUERY_SELECT_XPATH = '//div[@data-test="ccfk-list-item" and text()="{}"]//..'
    _FILTER_CLOSE_XPATH = '//div[contains(@id, "chip-closeButton-content")]'
    _PLAN_BODY_XPATH = '//div[@ref="eBodyViewport"]'
    _PLAN_COL_ID = {"plan_name": "name",
                    "description": "description",
                    "date": "createdOn",
                    "owner": "createdBy",
                    "import_status": "importStatus"
                    # "download_status": "downloadStatus",
                    # "activation_status": "activationStatus"
                    }

    _PLAN_ROW_NUM = '//div[@row-index]/div[@col-id="name"]'
    _PLAN_COL_XPATH = '//div[@row-index="{}"]/div[@col-id="{}"]'

    # For plan import
    # _OPEN_FILE_IMPORT_WINDOW = '//div[@id="import-plan-button-content"]'
    _PLAN_FILE_PATH_INPUT_FIELD = '//input[@type="file"]'
    _PLAN_NAME_INPUT_FIELD = '//input[@id="textInput-textInput"]'
    _IMPORT_BUTTON = '//span[text()="Import"]/..'

    # For SWM
    # _SW_VERSION_ROW_NUM = '//div[@row-index]/div[@col-id="packageName"]'
    _SW_VERSION_ROW = '//*[text() = "{}"]'

    # For integration plans
    _INTEGRATION_PLAN_CHECKBOX = '//span[text()="{}"]/../span[@class="ag-selection-checkbox"]'
    _USE_CASE_SPECIFIC_WORKFLOWS_BUTTON = '//div[@id="more-button-subMenuBtn-content"]'
    _USE_CASE_SPECIFIC_WORKFLOWS_OPTION_MAP = {'Integration plan import': '//li[@id="integrationPlanImport"]',
                                               'Integrate': '//li[@id="integrate"]',
                                               'Check against rule': '//li[@id="rulesCheckConsistency"]'}
    _INTEGRATE_PLAN_XPATH = '//button[@aria-label="integrate"]'
    _SETTINGS_PANEL = '//div[@id="expansionPanel"]/div[2]'
    _PRIVATE_KEY_PATH_INPUT_FIELD = '//input[@type="file"]'
    _INTEGRATE_OPERATION_BUTTON = '//div[@id="run-content"]'
    _REINTEGRATE_CHECKBOX = '//div[contains(@class, "ripple")]'

    _PREVIEW_REPORT_BUTTON = '//div[contains(@row-id, "{}")]//button[@aria-label="preview"]'
    _MORE_BUTTON = '//div[@row-id="{}"]//button[@aria-label="More Actions"]'
    _RUN_BUTTON = '//button[@id="run-button"]'
    _CLOSE_BUTTON = '//button[@id="cancel-button"]'

    def _select_use_case_on_storage_page(self, option_text):
        self.click_element_by_xpath(self._USE_CASE_ELEMENT_ON_STORAGE_PAGE)
        self.click_element_by_xpath(self._USE_CASE_OPTION_MAP[option_text])
        time.sleep(3)
        # self.element_exists(locator=(By.XPATH, self._STORAGE_PAGE_LOAD_FINISH_XPATH), timeout=10)

    def _input_plan_filter_context(self, **kwargs):
        filter_condition = {}
        for key, value in kwargs.items():
            if key not in self.ALL_FILTER_CONDITIONS:
                raise Exception("Got an unexpected filter condition-{}, "
                                "the condition should be in {}".format(key, ', '.join(self.ALL_FILTER_CONDITIONS)))
            if key == "plan_name" or key == "package_name" or key == 'report_name':
                key = key.replace('_', ' ').title()
            else:
                key = key.replace('_', ' ').capitalize()
            filter_condition[key] = value

        if 'Condition' in filter_condition.keys():
            condition = filter_condition['Condition']
            filter_condition.pop('Condition')
        else:
            condition = '='
        self._clear_filter()

        for key, value in filter_condition.items():
            self.insert_text_to_enable_element(locator=(By.XPATH, self._FILTER_FIRST_FIELD_XPATH),
                                               text=key)
            self.insert_text_to_enable_element(locator=(By.XPATH, self._FILTER_CONDITION_INPUT_XPATH),
                                               text=condition)
            if condition == '=':
                filter_condition_xpath = self._FILTER_CONDITION_SELECT_XPATH.format('Equal')
            elif condition == ':':
                filter_condition_xpath = self._FILTER_CONDITION_SELECT_XPATH.format('Contain')
            elif condition == '!=':
                filter_condition_xpath = self._FILTER_CONDITION_SELECT_XPATH.format('Not equals')
            elif condition == 'in':
                filter_condition_xpath = self._FILTER_CONDITION_SELECT_XPATH.format('In')
            else:
                raise Exception('condition type not support')
            self.wait_for_visibility(locator=(By.XPATH, filter_condition_xpath))
            self.click_element_by_xpath(filter_condition_xpath)

            self.insert_text_to_enable_element(locator=(By.XPATH, self._FILTER_QUERY_INPUT_XPATH),
                                               text=value)
            self.wait_for_visibility(locator=(By.XPATH, self._FILTER_QUERY_SELECT_XPATH.format(value)))
            self.click_element_by_xpath(self._FILTER_QUERY_SELECT_XPATH.format(value))

        self.wait_for_visibility(locator=(By.XPATH, self._PLAN_BODY_XPATH))

    def _clear_filter(self):
        if self.element_exists((By.XPATH, self._FILTER_CLOSE_XPATH)):
            elements = self._driver.find_elements_by_xpath(self._FILTER_CLOSE_XPATH)
            for element in elements:
                element.click()

    def get_plan_file_info(self, **kwargs):
        # self._driver.switch_to_frame("plan-view")
        self._driver.switch_to.frame(self._driver.find_element_by_name("plan-view"))
        self._select_use_case_on_storage_page("Plans")

        if kwargs:
            self._input_plan_filter_context(**kwargs)
        time.sleep(5)
        plan_list = []
        row_objects = self._driver.find_elements_by_xpath(self._PLAN_ROW_NUM)
        row_num = len(row_objects)
        for row_index in range(0, row_num):
            plan_info_dict = {}
            for key in self._PLAN_COL_ID:
                cid = self._PLAN_COL_ID[key]
                xpath = self._PLAN_COL_XPATH.format(row_index, cid)
                if len(self.get_attribute_by_xpath(xpath, "title")) > 0:
                    plan_info_dict[key] = self.get_attribute_by_xpath(xpath, "title")
                else:
                    plan_info_dict[key] = self.get_text_by_xpath(xpath)
            plan_list.append(plan_info_dict)
        self._driver.switch_to_default_content()
        return plan_list

    def import_plan(self, path_of_plan_file, plan_name, file_type):
        # self._driver.switch_to_frame("plan-view")
        self._driver.switch_to.frame(self._driver.find_element_by_name("plan-view"))
        if file_type == "plan":
            self._select_use_case_on_storage_page("Plans")
            self.click_element_by_xpath('//*[@id="more-button-subMenuBtn-content"]')
            self.click_element_by_xpath('//*[@id="cmPlanImport"]')
        elif file_type == "integration_plan":
            self._select_use_case_on_storage_page("Integration plans")
            self.click_element_by_xpath(self._USE_CASE_SPECIFIC_WORKFLOWS_BUTTON)
            time.sleep(2)
            self.click_element_by_xpath(self._USE_CASE_SPECIFIC_WORKFLOWS_OPTION_MAP["Integration plan import"])

        time.sleep(2)
        ele = self._driver.find_element_by_xpath(self._PLAN_FILE_PATH_INPUT_FIELD)
        ele.send_keys(path_of_plan_file)
        time.sleep(2)
        if plan_name:
            plan_name_field = self._driver.find_element_by_xpath(self._PLAN_NAME_INPUT_FIELD)
            self.input_text_to_field_by_element(plan_name_field, plan_name)
            time.sleep(3)
        self.click_element_by_xpath(self._IMPORT_BUTTON)
        self._driver.switch_to_default_content()
        # self.click_element_by_xpath(self._STORAGE_TOOLBAR)
        # self.wait_for_visibility(locator=(By.XPATH, self._STORAGE_PAGE_LOAD_FINISH_XPATH))

    def get_number_of_sw_version(self, sw_version):
        # self._driver.switch_to_frame("plan-view")
        self._driver.switch_to.frame(self._driver.find_element_by_name("plan-view"))
        self._select_use_case_on_storage_page("SW packages")
        row_objects = self._driver.find_elements_by_xpath(self._SW_VERSION_ROW.format(sw_version))
        row_num = len(row_objects)
        self._driver.switch_to_default_content()
        return row_num

    def integrate_from_plan(self, plan_name, reintegrate, path_of_private_key):
        # self._driver.switch_to_frame("plan-view")
        self._driver.switch_to.frame(self._driver.find_element_by_name("plan-view"))

        self._select_use_case_on_storage_page("Integration plans")
        self._input_plan_filter_context(plan_name=plan_name)
        time.sleep(3)
        self.click_element_by_xpath(self._INTEGRATION_PLAN_CHECKBOX.format(plan_name))
        self.click_element_by_xpath(self._INTEGRATE_PLAN_XPATH)
        self._driver.switch_to_default_content()
        # self._driver.switch_to_frame("workflow_configuration-view")
        self._driver.switch_to.frame(self._driver.find_element_by_name("workflow_configuration-view"))
        self.wait_for_enable(locator=(By.XPATH, self._SETTINGS_PANEL), timeout=60)
        if reintegrate:
            self.click_element_by_xpath(self._SETTINGS_PANEL)
            time.sleep(2)
            self.click_element_by_xpath(self._REINTEGRATE_CHECKBOX)
            time.sleep(2)
        if path_of_private_key:
            ele = self._driver.find_element_by_xpath(self._PRIVATE_KEY_PATH_INPUT_FIELD)
            ele.send_keys(path_of_private_key)
        self.click_element_by_xpath(self._INTEGRATE_OPERATION_BUTTON)
        self._driver.switch_to_default_content()

    def storage_get_failure_info(self, report_name):
        self._driver.maximize_window()
        self._driver.switch_to.frame(self._driver.find_element_by_name("plan-view"))
        self._driver.implicitly_wait(5)
        self._select_use_case_on_storage_page("Consistency reports")
        self._input_plan_filter_context(report_name=report_name, condition=':')
        time.sleep(3)
        _REPORT_BUTTON = self._PREVIEW_REPORT_BUTTON.format(report_name)
        self.click_element_by_xpath(_REPORT_BUTTON)
        time.sleep(3)
        elements = self._driver.find_elements_by_xpath('//div[@class="view-line"]')
        failure_info = ''
        for i in range(len(elements)):
            _xpath = '//div[@class="view-lines"]/div[%s]/span/span[contains(@class, "mtk")]' % str(i + 1)
            element_list = self._driver.find_elements_by_xpath(_xpath)
            for element in element_list:
                info = element.get_attribute("textContent").strip()
                info = info.replace(u'\xa0', ' ')
                failure_info = failure_info + info
        try:
            close_path = '//div[@id="close-button"]'
            self._driver.implicitly_wait(3)
            self.click_element_by_xpath(close_path)
            self._driver.switch_to_default_content()
        finally:
            return eval(failure_info)

    def storage_plan_check_against_rules(self, plan_name, name, validation_rules='CU DU consistency'):
        # self._driver.maximize_window()
        self._driver.set_window_size(width=1296, height=696)
        self._driver.switch_to.frame(self._driver.find_element_by_name("plan-view"))
        self._driver.implicitly_wait(5)
        self._select_use_case_on_storage_page("Plans")

        self._input_plan_filter_context(plan_name=plan_name)
        time.sleep(3)

        self.click_element_by_xpath(self._INTEGRATION_PLAN_CHECKBOX.format(plan_name))
        self.click_element_by_xpath(self._MORE_BUTTON.format(plan_name))
        time.sleep(1)
        self.click_element_by_xpath(self._USE_CASE_SPECIFIC_WORKFLOWS_OPTION_MAP["Check against rule"])
        self._driver.switch_to_default_content()

        self._driver.implicitly_wait(10)

        self._driver.switch_to.frame(self._driver.find_element_by_name("workflow_configuration-view"))
        name_path = '//input[@id="name-textInput"]'
        plan_name_field = self._driver.find_element_by_xpath(name_path)
        self.input_text_to_field_by_element(plan_name_field, name)

        filter_path = '//input[@id="filter-input-text-input-textInput"]'
        self.input_text_to_field_by_element(self._driver.find_element_by_xpath(filter_path), validation_rules)

        time.sleep(3)
        consistency_button_path = '//*[@id="{}-toggleInput"]/div[1]'.format(validation_rules)
        self.wait_for_visibility(locator=(By.XPATH, consistency_button_path))
        self.click_element_by_xpath(consistency_button_path)
        self.click_element_by_xpath(self._RUN_BUTTON)
        self._driver.implicitly_wait(3)
        self.click_element_by_xpath(self._CLOSE_BUTTON)
        self._driver.switch_to_default_content()
